<div class="form-grid"><div class="field"><label>Name</label><input name="name" value="{{ old('name',$leaveType->name) }}" required></div><div class="field"><label>Annual allowance</label><input type="number" name="annual_allowance" min="0" max="365" value="{{ old('annual_allowance',$leaveType->annual_allowance) }}" required></div><div class="field"><label>Color</label><input type="color" name="color" value="{{ old('color',$leaveType->color ?: '#2563eb') }}" required></div><div class="field"><label>Status</label><select name="is_active"><option value="1" @selected(old('is_active',$leaveType->is_active))>Active</option><option value="0" @selected(!old('is_active',$leaveType->is_active))>Inactive</option></select></div><div class="field full-width"><label>Description</label><textarea name="description" rows="4">{{ old('description',$leaveType->description) }}</textarea></div><label class="check"><input type="checkbox" name="tracks_balance" value="1" @checked(old('tracks_balance',$leaveType->tracks_balance))> Track yearly balance</label></div>
